# Syntax found on a line. Checked in order against the code (comments removed).
SYNTAX = [
    ("shebang", r"^#!", "#! (shebang)", "The first line says which program runs the script: '#!/usr/bin/env bash' finds bash wherever it is installed."),
    ("funcdef", r"^\s*(function\s+)?[A-Za-z_][A-Za-z0-9_]*\s*\(\)", "Function definition", "name() { ... } defines a function: nothing in it runs now. Call it like a command, 'name arg1 arg2'; inside, the arguments are $1, $2, ... ($@ = all of them, $# = how many). It reports success or failure with return, like any command."),
    ("if", r"(^|[;&|]\s*|\bthen\s+|\belse\s+|\bdo\s+)\s*(if|elif)\b", "if / elif / else / fi", "Runs the block only if the command after 'if' succeeds (exit code 0). A test like [[ ... ]] or (( ... )) is such a command, but so is any other command or function: 'if grep -q x file' means 'if grep finds x'."),
    ("dbracket", r"\[\[", "[[ ... ]] (test)", "Bash's test command: it succeeds when the condition is true. -z \"$x\" empty, -n not empty, -f file exists, -d folder exists, -e exists, -s file not empty, -x executable; == equal (or matches a glob like *text*), != not equal, =~ matches a regex; && and || combine tests; ! negates."),
    ("arith", r"\(\(", "(( ... )) (arithmetic)", "Whole-number math. As a command it succeeds when the result is not 0, so (( DRY_RUN )) means 'DRY_RUN is on'. Variables inside don't need $. (( n++ )) adds 1; $(( a + b )) puts the result in the text."),
    ("case", r"(^|\s)case\b.*\bin\b", "case ... in ... esac", "Compares one value against patterns, top to bottom; the first pattern that matches runs its commands, up to ;;. Patterns are globs: * matches anything, a|b means a or b, -* means 'starts with -'."),
    ("for", r"(^|[;&|]\s*)\s*for\b", "for loop", "for x in a b c; do ...; done runs the body once for each item, with $x set to it. for (( i = 0; i < n; i++ )) counts instead."),
    ("while", r"(^|[;&|]\s*)\s*(while|until)\b", "while / until loop", "Repeats the body while the command after 'while' succeeds ('until': while it fails). 'while read -r line; do ...; done < file' handles a file one line at a time."),
    ("cmdsub", r"\$\(", "$( ... ) (command substitution)", "Runs the command inside and puts its output here, as text (the trailing newline removed). x=\"$(cmd)\" stores the output in x."),
    ("procsub", r"<\(", "<( ... ) (process substitution)", "Runs the command and makes its output look like a file. 'done < <(cmd)' feeds the output to a loop without a pipe, so variables set in the loop are still set after it."),
    ("default", r"\$\{[^}]*:-", "${var:-default}", "The variable's value, or the default when the variable is unset or empty. ${var-default} (no colon) only when it is unset."),
    ("assign_default", r"\$\{[^}]*:=", "${var:=default}", "Like :- but also stores the default in the variable."),
    ("required", r"\$\{[^}]*:\?", "${var:?message}", "Stops the script with the message if the variable is unset or empty."),
    ("alt", r"\$\{[^}]*\[@\]\+", "${arr[@]+\"${arr[@]}\"}", "A safe way to write all items of an array that may be empty: with set -u, plain \"${arr[@]}\" on an empty array is an error in older Bash. It means: if arr is set, its items; otherwise nothing."),
    ("trim", r"\$\{[A-Za-z_#][^}]*?(##?|%%?)", "${var#...} / ${var%...}", "Cuts a pattern off the value: # from the start, % from the end (## and %% cut the longest match). ${path##*/} is the file name, ${path%/*} the folder, ${kv%%=*} the part before the first =."),
    ("replace", r"\$\{[A-Za-z_][A-Za-z0-9_]*(\[[^]]*\])?//?[^}]", "${var/old/new}", "The value with old replaced by new (// replaces every match)."),
    ("length", r"\$\{#", "${#var}", "The length of the value; ${#arr[@]} is the number of items in an array."),
    ("case_conv", r"\$\{[^}]*(\^\^|,,)\}", "${var^^} / ${var,,}", "The value in upper case (^^) or lower case (,,)."),
    ("array_all", r"\[@\]", "\"${arr[@]}\" (all items)", "All items of an array, each kept as one word when quoted. \"${arr[*]}\" joins them into one string with spaces."),
    ("array_set", r"[A-Za-z_][A-Za-z0-9_]*\+?=\(", "Array (list)", "name=(a b c) makes an array; name+=(d) adds an item; ${name[0]} is the first item, ${name[@]} all of them, ${#name[@]} how many."),
    ("assoc", r"\[[^]]*\]=", "arr[key]=value", "Sets one item of an array (a numbered one, or one by name in an associative array made with declare -A)."),
    ("status", r"\$\?", "$?", "The exit code of the last command: 0 = success."),
    ("argc", r"\$#", "$#", "How many arguments the script or function got."),
    ("argv", r"\$@|\$\*", "$@", "All the arguments. \"$@\" keeps each one as a separate word, even if it has spaces."),
    ("posarg", r"\$[1-9]|\$\{[1-9]", "$1, $2, ...", "The arguments: inside a function, the ones the function was called with; outside, the script's own."),
    ("pid", r"\$\$", "$$", "This shell's process id. Here it marks who holds the lock."),
    ("bgpid", r"\$!", "$!", "The process id of the command just started in the background with &."),
    ("pipestatus", r"PIPESTATUS", "PIPESTATUS", "An array with the exit code of each command in the last pipeline. ${PIPESTATUS[0]} is the first one's: a pipe's own exit code is the last command's, so this gets the one that matters."),
    ("lineno", r"\$LINENO|BASH_LINENO|FUNCNAME", "$LINENO", "The line number being run; used to say where something failed."),
    ("or_true", r"\|\|\s*true\b", "|| true", "Ignores a failure. With set -e, a failing command stops the script; '|| true' makes this one always succeed."),
    ("or", r"\|\|", "|| (or else)", "Runs the right side only if the left side failed. 'test || die msg' reads: 'make sure test is true, or stop'."),
    ("and", r"&&", "&& (and then)", "Runs the right side only if the left side succeeded. 'test && cmd' reads: 'if test, cmd'."),
    ("not", r"(^|[;&|(]\s*|\bif\s+|\bwhile\s+)!\s", "! (not)", "Reverses the result: '! cmd' succeeds when cmd fails."),
    ("group", r"(\|\||&&)\s*\{", "{ ...; } (group)", "Runs several commands as one, e.g. 'test || { msg; exit 1; }' does both only when the test fails. It needs the spaces and the last ;."),
    ("subshell", r"(^|[;&|]\s*)\(\s*[a-z]", "( ... ) (subshell)", "Runs the commands in a copy of the shell: a cd or variable change inside doesn't affect the rest of the script."),
    ("errout", r"2>&1", "2>&1", "Sends errors (stream 2) to the same place as normal output (stream 1), so both are captured or both are hidden."),
    ("tostderr", r">&2", ">&2", "Writes to the error stream (stderr) instead of normal output: it still shows on screen, but isn't captured by $( ... ) or a pipe."),
    ("null", r">\s*/dev/null", ">/dev/null", "Throws the output away. 2>/dev/null throws away only the error messages."),
    ("heredoc", r"(^|[^<])<<-?\s*['\"]?[A-Za-z_]+", "<<EOF (here-document)", "The lines below, up to the closing word, are fed to the command as its input. When the word is quoted (<<'REMOTE'), the text is passed exactly as written: no $variables are filled in here, so it can be a script for another machine."),
    ("herestring", r"<<<", "<<< (here-string)", "Feeds this text to the command as its input, like echo text | cmd."),
    ("append", r"(^|[^>&0-9])>>", ">> (append)", "Adds the output to the end of the file."),
    ("redirect", r"(^|[^>&0-9<-])>\s*[\"$/A-Za-z{]", "> (write to a file)", "Writes the output to a file, replacing what was in it."),
    ("input", r"(^|[^<])<\s+[\"$/A-Za-z]", "< (read from a file)", "The command reads its input from the file."),
    ("pipe", r"[^|]\|\s*[A-Za-z\"$]", "| (pipe)", "The output of the left command becomes the input of the right one."),
    ("background", r"[^&>]&\s*$|[^&>]&\s+[^&]", "& (in the background)", "Starts the command and goes on at once, without waiting for it to finish."),
    ("glob_match", r"==\s*\*|==\s*\"?[^\"]*\*\"?\s*\]\]|\*\"[^\"]*\"\*", "== *text* (pattern match)", "Inside [[ ]], == with an unquoted * compares against a pattern: [[ $x == *abc* ]] means 'x contains abc'. Quoted parts are matched literally."),
    ("regex", r"=~", "=~ (regex match)", "Inside [[ ]], succeeds when the value matches the regular expression on the right. ^ is the start, $ the end, [A-Za-z0-9] one such character, + one or more, * zero or more."),
    ("ansi_c", r"\$'", "$'...' (escapes)", "A string where \\n, \\t and \\e mean newline, tab and escape."),
    ("octal", r"8#", "8#... (octal)", "A number in base 8, as file permissions are written: 8#077 is the group and others bits."),
]

# Words of a [[ ... ]] test, as phrases. {a} = left side, {b} = right side.
TESTS = {
    "-z": "{a} is empty",
    "-n": "{a} is not empty",
    "-f": "{a} is a file that exists",
    "-d": "{a} is a folder that exists",
    "-e": "{a} exists",
    "-s": "{a} exists and is not empty",
    "-x": "{a} exists and can be run",
    "-r": "{a} can be read",
    "-w": "{a} can be written",
    "-L": "{a} is a symbolic link",
    "-h": "{a} is a symbolic link",
    "-p": "{a} is a named pipe",
    "-t": "file descriptor {a} is a terminal (someone is typing)",
    "-v": "the variable {a} is set",
    "==": "{a} is {b}",
    "=": "{a} is {b}",
    "!=": "{a} is not {b}",
    "=~": "{a} matches the regex {b}",
    "-eq": "{a} equals {b}",
    "-ne": "{a} is not {b}",
    "-lt": "{a} is less than {b}",
    "-le": "{a} is at most {b}",
    "-gt": "{a} is greater than {b}",
    "-ge": "{a} is at least {b}",
    "-nt": "{a} is newer than {b}",
    "-ot": "{a} is older than {b}",
    "<": "{a} sorts before {b}",
    ">": "{a} sorts after {b}",
}

TRAPS = {"EXIT": "the script ends (for any reason)", "ERR": "a command fails", "INT": "Ctrl-C is pressed",
         "TERM": "it is asked to stop (kill)", "HUP": "its terminal goes away", "QUIT": "Ctrl-\\ is pressed",
         "RETURN": "a function returns", "DEBUG": "before every command"}

