HINTS = {
    "log": "writes a time-stamped line to the screen (stderr) and to the run's log file",
    "info": "logs an INFO line on screen and in the run's log",
    "warn": "logs a WARN line on screen and in the run's log",
    "err": "logs an ERROR line on screen and in the run's log",
    "die": "logs an ERROR line and stops the script (exit 1)",
    "usage": "prints the help text (the comment block at the top of the file)",
    "main": "the script's starting point: reads the options, then runs the phases in order",
    "parse_args": "reads the command-line options into the settings variables",
    "load_config": "reads the config file, whose settings replace the defaults",
}

# What a trap command reads like, by the command it sets.
SIGNAL_EXIT = {"130": "Ctrl-C", "143": "a kill", "129": "a hangup"}
